        allowed = set(n for n in nodes if n not in forb)
        gg = {n: [] for n in allowed}
        for (a,b,c,up) in linklist:
            if up and a in allowed and b in allowed and (a,b)!=(u,v):
                gg[a].append((b,c))
        tail = dijkstra(gg, u, D, allowed)
        if tail is None: return "need5"
        tc, tp = tail
        pfx_cost = sum(costmap[(pp[i],pp[i+1])] for i in range(h))
        repairs.append((pfx_cost+tc, pp[:h+1]+tp[1:]))
    # simulation
    state = dict(state0)
    pedges = set(zip(pp,pp[1:]))
    redges = [set(zip(p,p[1:])) for _,p in repairs]
    pdown = 0; rdown=[0]*len(repairs)
    def allup(edges):
        return all(state[e] for e in edges)
    def target():
        if pdown==0: return (pc, pp)
        best=None
        for (rc,rp),re_ in zip(repairs,redges):
            if all(re_) and (best is None or (rc,rp)<best):
                best=(rc,rp)
        return best
    def ro(r): return [r[0],r[1]] if r is not None else [None,[]]
    installed=(pc,pp); tstart=None; tat=None; tt=None
    events=[]; done_count=0; i=0; n=len(items)
    while i<n or tat is not None:
        wakes=[]
        if i<n: wakes.append(items[i][0])
        if tat is not None: wakes.append(tat)
        now=min(wakes)
        while i<n and items[i][0]==now:
            _,u,v,up = items[i]; i+=1
            real=0
            if state[(u,v)]!=up:
                state[(u,v)]=up; real=1
                d=-1 if up else 1
                if (u,v) in pedges: pdown+=d
                for j,re_ in enumerate(redges):
                    if (u,v) in re_: rdown[j]+=d
                new=target()
                if new!=installed:
                    due=now+W
                    if due>MAXC: return "need5"
                    tstart=now; tat=due; tt=new
                else:
                    tstart=tat=tt=None
            events.append([now,0,u,v,up,real,ro(installed),
                           ro(tt if tat is not None else installed),tat])
        if tat is not None and tat==now:
            old=installed; installed=tt
            events.append([now,1,ro(old),ro(installed),now-tstart])
            done_count+=1
            tstart=tat=tt=None
    b=[[pp[h],pp[h+1],[repairs[h][0],repairs[h][1]]] for h in range(len(pp)-1)]
    return {"s":S,"d":D,"m":[pc,pp],"b":b,"e":events,"r":done_count,
            "f":ro(installed)}

def rand_topo(rng):
    Vn = rng.randint(2,5)
    names = [chr(ord('A')+i) for i in range(Vn)]
    nodes = ["S"] + [x for x in names if x not in ("S","D")]
    # ensure D present
    nodes = ["S"] + [chr(ord('a')+i) for i in range(Vn-2)] + ["D"]
    nodes = list(dict.fromkeys(nodes))
    edges={}
    for u in nodes:
        for v in nodes:
            if u!=v and rng.random()<0.45:
                edges[(u,v)] = rng.randint(1,9)
    linklist=[(u,v,c,rng.random()<0.85) for (u,v),c in edges.items()]
    return nodes, linklist

def run(netfile, S, D, W, data):
    p=subprocess.run([sys.executable,RELAY,"lrepair",netfile,S,D,str(W),
                      json.dumps(data)],capture_output=True)
    return p.returncode, p.stdout.decode()

def main():
    rng=random.Random(1234)
    trials=0
    for it in range(3000):
        nodes, ll = rand_topo(rng)
        # topology file with metrics
        topo={"nodes":nodes,"links":[{"from":u,"to":v,"cost":c,"up":up,
              "bandwidth":1,"latency":0} for (u,v,c,up) in ll]}
        fn="/tmp/fz.json"
        open(fn,"w").write(json.dumps(topo))
        # check primary exists and repairs exist by reference
        W=rng.randint(0,5)
        Q=rng.randint(0,6)
        items=[]; t=0
        pairs=[(u,v) for (u,v,c,up) in ll]
        if not pairs: continue
        for _ in range(Q):
            t += rng.randint(0,2)
            u,v = pairs[rng.randrange(len(pairs))]
            up = rng.random()<0.5
            items.append([t,u,v,up])
        try:
            expected = ref(nodes,ll,"S","D",W,items)
        except Exception as ex:
            continue
        rc,out = run(fn,"S","D",W,items)
        if expected=="need5":
            if rc!=5:
                print("EXPECTED 5 but got",rc,out); print(topo); print(items); return
            continue
        if rc!=0:
            print("UNEXPECTED",rc,out); print(topo); print(items); return
        got=json.loads(out)
        if got!=expected:
            print("MISMATCH")
            print("topo",json.dumps(topo,ensure_ascii=False))
            print("W",W,"items",items)
            print("got ",json.dumps(got,ensure_ascii=False))
            print("want",json.dumps(expected,ensure_ascii=False))
            return
        trials+=1
    print("OK",trials,"trials")

