def dijkstra_ref(nodes, edges_up, src, dst, allowed=None):
    # edges_up: dict u->list of (v,c); returns (cost,path) or None
    if allowed is None: allowed=set(nodes)
    INF=10**30
    dist={n:INF for n in allowed}; dist[src]=0
    par={n:None for n in allowed}
    done=set()
    while True:
        u=None
        for n in allowed:
            if n not in done and (u is None or dist[n]<dist[u]): u=n
        if u is None or dist[u]==INF: break
        done.add(u)
        for w,c in edges_up.get(u,[]):
            if w not in allowed or w in done: continue
            nd=dist[u]+c
            cand=None
            if nd<dist[w]: cand=1
            elif nd==dist[w]:
                p=[]
                x=u
